using YourApi;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<GlobalExceptionHandler>();

var app = builder.Build();

app.UseExceptionHandler();    // Invokes IExceptionHandler implementations
app.UseStatusCodePages();     // Converts empty error responses to ProblemDetails

// Sample endpoints to demonstrate
app.MapGet("/items/{id}", (int id) =>
{
    if (id == 0) throw new KeyNotFoundException($"Item {id} not found.");
    if (id < 0) throw new ArgumentException("ID must be positive.");
    if (id == 99) throw new InvalidOperationException("Item is in conflicting state.");
    if (id == 13) throw new Exception("Something unexpected");

    return Results.Ok(new { Id = id, Name = "Widget" });
});

app.Run();

